import random

def random_fill_array(n, k):
    if n <= 0 or k <= 0:
        return []
    arr = [random.randint(0, k-1)]
    for _ in range(1, n):
        x = random.randint(0, k-1)
        while x == arr[-1]:
            x = random.randint(0, k-1)
        arr.append(x)
    return arr

def edit_distance_with_operations(str1, str2):
    m = len(str1)
    n = len(str2)

    distance = [[0 for _ in range(n + 1)] for _ in range(m + 1)]
    operations = [["" for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                distance[i][j] = j
                operations[i][j] = "Insert " + str2[:j]
            elif j == 0:
                distance[i][j] = i
                operations[i][j] = "Delete " + str1[:i]
            elif str1[i - 1] == str2[j - 1]:
                distance[i][j] = distance[i - 1][j - 1]
                operations[i][j] = operations[i - 1][j - 1]
            else:
                replace_cost = distance[i - 1][j - 1] + 1
                remove_cost = distance[i - 1][j] + 1
                insert_cost = distance[i][j - 1] + 1
                min_cost = min(replace_cost, remove_cost, insert_cost)
                distance[i][j] = min_cost
                if min_cost == replace_cost:
                    operations[i][j] = operations[i - 1][j - 1] + "Replace " + str1[i - 1] + " with " + str2[j - 1] + "; "
                elif min_cost == remove_cost:
                    operations[i][j] = operations[i - 1][j] + "Delete " + str1[i - 1] + "; "
                else:
                    operations[i][j] = operations[i][j - 1] + "Insert " + str2[j - 1] + "; "

    return distance[m][n], operations[m][n]

if __name__ == '__main__':
    str1 = "I am eating"
    str2 = "I am eating a sandwich"
    distance, ops = edit_distance_with_operations(str1, str2)
    print("Edit Distance:", distance)
    print("Operations:", ops)

