def is_a_power_of(base, number):
    if base == 0:
        return number == 0
    if base < 0:
        if number < 0:
            return is_a_power_of(-base, -number)
        else:
            return False
    if base == 1:
        return number == 1
    if base == -1:
        return number == 1 or number == -1
    current = base
    while abs(current - number) > 1e-6:
        if current > number:
            return False
        current *= base
    return True

