def get_largest_common_divisor(numbers):
    if len(numbers) == 0:
        return 0

    def compute_gcd(a, b):
        while a != 0 and b != 0:
            if a > b:
                a %= b
            else:
                b %= a
        return a + b

    gcd = numbers[0]
    for num in numbers[1:]:
        gcd = compute_gcd(gcd, num)

    return gcd

