function maxSumWithConstraints(arr):
    n = length(arr)
    if n == 0:
        return 0
    if n == 1:
        return arr[0]

    dp_pick = [0] * n
    dp_skip = [0] * n

    dp_pick[0] = arr[0]
    dp_skip[0] = 0

    for i from 1 to n-1:
        dp_pick[i] = arr[i] + dp_skip[i-1]
        dp_skip[i] = max(dp_pick[i-1], dp_skip[i-1])

    return max(dp_pick[n-1], dp_skip[n-1])
```

