public class ArrayIndexRetriever {
    public static int getItemAtIndex(int[] arr, int index) {
        if (index >= arr.length || index < -arr.length) {
            return -1;
        }
        if (index < 0) {
            index = arr.length + index;
        }
        return arr[index];
    }

    public static void main(String[] args) {
        int[] arr = {11, 30, 45, 19, 20, 60};
        System.out.println(getItemAtIndex(arr, 3));  // Output: 19
        System.out.println(getItemAtIndex(arr, -3)); // Output: 19
        System.out.println(getItemAtIndex(arr, 7));  // Output: -1
        System.out.println(getItemAtIndex(arr, -7)); // Output: -1
    }
}

