public class SearchAlgorithm {
  public int search(int[] array, int target) {
    int left = 0;
    int right = array.length - 1;
    int result = -1;

    while (left <= right) {
      int mid = (left + right) / 2;

      if (array[mid] == target) {
        result = mid;
        right = mid - 1;  // Continue searching in the left half
      } else if (target < array[mid]) {
        right = mid - 1;
      } else {
        left = mid + 1;
      }
    }
    return result;
  }
}

