def find_pairs(nums, target_sum):
    used = set()
    result = []

    for i in range(len(nums)):
        if nums[i] in used:
            continue
        for j in range(i + 1, len(nums)):
            if nums[j] in used:
                continue
            if nums[i] + nums[j] == target_sum:
                result.append((nums[i], nums[j]))
                used.add(nums[i])
                used.add(nums[j])
                break

    result.sort(key=lambda x: x[0])
