import java.util.*;

public class ArraySort {
    public static Map<Integer, Integer> sortArrayAndCount(int[] arr) {
        // Step 1: Count occurrences of each element
        Map<Integer, Integer> counts = new HashMap<>();
        for (int num : arr) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        // Step 2: Extract keys and sort them
        List<Integer> sortedKeys = new ArrayList<>(counts.keySet());
        Collections.sort(sortedKeys);

        // Step 3: Prepare the result map with sorted keys and their counts
        Map<Integer, Integer> sortedCounts = new LinkedHashMap<>();
        for (int key : sortedKeys) {
            sortedCounts.put(key, counts.get(key));
        }

        return sortedCounts;
    }

    public static void main(String[] args) {
        int[] arr = {4, 2, 2, 8, 3, 3, 1};
        Map<Integer, Integer> result = sortArrayAndCount(arr);

        System.out.println("Sorted Array with Counts:");
        for (Map.Entry<Integer, Integer> entry : result.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}

