def generateFib(n):
    # Dictionary to store Fibonacci numbers
    fib_memo = {0: [], 1: [0], 2: [0, 1]}

    def fibonacci(k):
        if k not in fib_memo:
            fib_memo[k] = fibonacci(k - 1) + [fib_memo[k - 1][-1] + fib_memo[k - 2][-1]]
        return fib_memo[k]

    if n <= 0:
        return []
    elif n in fib_memo:
        return fib_memo[n]
    else:
        return fibonacci(n)

