def reverse_words_with_punctuation(sentence):
    words = sentence.split(' ')
    processed_words = []
    for word in words:
        punctuation = ''
        while word and word[-1] in ['.', ',', '!', '?']:
            punctuation += word[-1]
            word = word[:-1]
        reversed_word = word[::-1]
        if punctuation:
            reversed_word = punctuation + reversed_word
        processed_words.append(reversed_word)
    return ' '.join(processed_words)

