import java.util.HashMap;
import java.util.Map;

public class VowelCounter {
    public static void main(String[] args) {
        String sentence = "Hi there, how are you doing?";
        Map<Character, Integer> vowelCounts = new HashMap<>();
        vowelCounts.put('a', 0);
        vowelCounts.put('e', 0);
        vowelCounts.put('i', 0);
        vowelCounts.put('o', 0);
        vowelCounts.put('u', 0);

        for (int i = 0; i < sentence.length(); i++) {
            char ch = Character.toLowerCase(sentence.charAt(i));
            if (vowelCounts.containsKey(ch)) {
                vowelCounts.put(ch, vowelCounts.get(ch) + 1);
            }
        }

        int totalCount = 0;
        for (char vowel : vowelCounts.keySet()) {
            totalCount += vowelCounts.get(vowel);
        }

        System.out.println("Total number of vowels in the string: " + totalCount);
        System.out.println("Breakdown of each vowel:");
        for (Map.Entry<Character, Integer> entry : vowelCounts.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}

