public class NumberToWordsConverter {

    public static String intToEnglish(int input) {
        if (input == 0) {
            return "zero";
        }

        String[] numbers1_19 = {"one", "two", "three", "four", "five", "six",
                "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen",
                "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
                "nineteen"};
        String[] multiplesOfTen = {"twenty", "thirty", "forty",
                "fifty", "sixty", "seventy", "eighty", "ninety"};
        String[] largeNumbers = {"", " thousand", " million", " billion"};

        StringBuilder output = new StringBuilder();
        int index = 0;

        while (input > 0) {
            if (input % 1000 != 0) {
                output.insert(0, helper(input % 1000) + largeNumbers[index] + " ");
            }
            input /= 1000;
            index++;
        }

        return output.toString().trim();
    }

    private static String helper(int num) {
        if (num == 0) {
            return "";
        } else if (num < 20) {
            return numbers1_19[num - 1];
        } else if (num < 100) {
            return multiplesOfTen[num / 10 - 2] + (num % 10 != 0 ? " " + numbers1_19[num % 10 - 1] : "");
        } else {
            return numbers1_19[num / 100 - 1] + " hundred" + (num % 100 != 0 ? " " + helper(num % 100) : "");
        }
    }

    public static void main(String[] args) {
        System.out.println(intToEnglish(123456789)); // Output: "one hundred twenty three million four hundred fifty six thousand seven hundred eighty nine"
        System.out.println(intToEnglish(0));         // Output: "zero"
        System.out.println(intToEnglish(1001));      // Output: "one thousand one"
        System.out.println(intToEnglish(1000000));   // Output: "one million"
    }
}

