def decimal_to_binary_twos_complement(num):
    def convert_positive_to_binary(num):
        binary = []
        while num > 0:
            binary.append(num % 2)
            num //= 2
        return binary

    def invert_bits(binary):
        return [1 - bit for bit in binary]

    def add_one(binary):
        carry = 1
        for i in range(len(binary) - 1, -1, -1):
            total = binary[i] + carry
            binary[i] = total % 2
            carry = total // 2
        if carry > 0:
            binary.insert(0, carry)

    def pad_with_zeros(binary, width):
        while len(binary) < width:
            binary.insert(0, 0)

    if num >= 0:
        binary = convert_positive_to_binary(num)
        pad_with_zeros(binary, 8)
    else:
        binary = convert_positive_to_binary(-num)
        invert_bits(binary)
        add_one(binary)
        pad_with_zeros(binary, 8)

    return binary

# Example usage:
print(decimal_to_binary_twos_complement(10))   # Output: [0, 0, 0, 0, 1, 0, 1, 0]
print(decimal_to_binary_twos_complement(-10))  # Output: [1, 1, 1, 1, 0, 1, 1, 0]

