class AVLNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.height = 1
        self.size = 1

class AVLTree:
    def insert(self, root, key):
        if not root:
            return AVLNode(key)
        elif key < root.key:
            root.left = self.insert(root.left, key)
        else:
            root.right = self.insert(root.right, key)

        root.height = 1 + max(self.get_height(root.left), self.get_height(root.right))
        root.size = 1 + self.get_size(root.left) + self.get_size(root.right)

        balance = self.get_balance(root)

        if balance > 1 and key < root.left.key:
            return self.right_rotate(root)

        if balance < -1 and key > root.right.key:
            return self.left_rotate(root)

        if balance > 1 and key > root.left.key:
            root.left = self.left_rotate(root.left)
            return self.right_rotate(root)

        if balance < -1 and key < root.right.key:
            root.right = self.right_rotate(root.right)
            return self.left_rotate(root)

        return root

    def delete(self, root, key):
        if not root:
            return root
        elif key < root.key:
            root.left = self.delete(root.left, key)
        elif key > root.key:
            root.right = self.delete(root.right, key)
        else:
            if root.left is None:
                temp = root.right
                root = None
                return temp
            elif root.right is None:
                temp = root.left
                root = None
                return temp

            temp = self.get_min_value_node(root.right)
            root.key = temp.key
            root.right = self.delete(root.right, temp.key)

        if root is None:
            return root

        root.height = 1 + max(self.get_height(root.left), self.get_height(root.right))
        root.size = 1 + self.get_size(root.left) + self.get_size(root.right)

        balance = self.get_balance(root)

        if balance > 1 and self.get_balance(root.left) >= 0:
            return self.right_rotate(root)

        if balance > 1 and self.get_balance(root.left) < 0:
            root.left = self.left_rotate(root.left)
            return self.right_rotate(root)

        if balance < -1 and self.get_balance(root.right) <= 0:
            return self.left_rotate(root)

        if balance < -1 and self.get_balance(root.right) > 0:
            root.right = self.right_rotate(root.right)
            return self.left_rotate(root)

        return root

    def left_rotate(self, z):
        y = z.right
        T2 = y.left

        y.left = z
        z.right = T2

        z.height = 1 + max(self.get_height(z.left), self.get_height(z.right))
        z.size = 1 + self.get_size(z.left) + self.get_size(z.right)
        y.height = 1 + max(self.get_height(y.left), self.get_height(y.right))
        y.size = 1 + self.get_size(y.left) + self.get_size(y.right)

        return y

    def right_rotate(self, z):
        y = z.left
        T3 = y.right

        y.right = z
        z.left = T3

        z.height = 1 + max(self.get_height(z.left), self.get_height(z.right))
        z.size = 1 + self.get_size(z.left) + self.get_size(z.right)
        y.height = 1 + max(self.get_height(y.left), self.get_height(y.right))
        y.size = 1 + self.get_size(y.left) + self.get_size(y.right)

        return y

    def get_height(self, root):
        if not root:
            return 0
        return root.height

    def get_size(self, root):
        if not root:
            return 0
        return root.size

    def get_balance(self, root):
        if not root:
            return 0
        return self.get_height(root.left) - self.get_height(root.right)

    def get_min_value_node(self, root):
        if root is None or root.left is None:
            return root
        return self.get_min_value_node(root.left)

    def kth_smallest(self, root, k):
        if root is None:
            return None

        left_size = self.get_size(root.left)

        if k == left_size + 1:
            return root.key
        elif k <= left_size:
            return self.kth_smallest(root.left, k)
        else:
            return self.kth_smallest(root.right, k - left_size - 1)

# Example usage:
avl_tree = AVLTree()
root = None
operations = [
    ("insert", 10),
    ("insert", 20),
    ("insert", 30),
    ("insert", 40),
    ("insert", 50),
    ("delete", 10),
    ("kth_smallest", 2)
]

for operation in operations:
    if operation[0] == "insert":
        root = avl_tree.insert(root, operation[1])
    elif operation[0] == "delete":
        root = avl_tree.delete(root, operation[1])
    elif operation[0] == "kth_smallest":
        result = avl_tree.kth_smallest(root, operation[1])
        print(f"The {operation[1]}-th smallest element is: {result}")
