using System;
using System.Collections.Generic;

public class Program {
    public static int[] splitEvenSum(string inputString) {
        List<int> nums = new List<int>();

        // Split inputString at , and add elements to the list
        foreach (var num in inputString.Split(',')) {
            nums.Add(int.Parse(num));
        }

        // Initialize variables
        int totalSum = 0;
        foreach (var num in nums) {
            totalSum += num;
        }
        int targetSum = totalSum / 2;
        bool[] dp = new bool[targetSum + 1];
        dp[0] = true;

        // Dynamic programming to find the closest sum to targetSum
        foreach (var num in nums) {
            for (int j = targetSum; j >= num; j--) {
                dp[j] = dp[j] || dp[j - num];
            }
        }

        // Find the closest sum to targetSum
        int sum1 = 0;
        for (int i = targetSum; i >= 0; i--) {
            if (dp[i]) {
                sum1 = i;
                break;
            }
        }

        int sum2 = totalSum - sum1;
        return new int[] { sum1, sum2 };
    }

    public static void Main() {
        string inputString = "1,2,3,4,5,6";
        int[] result = splitEvenSum(inputString);
        Console.WriteLine($"Sum1: {result[0]}, Sum2: {result[1]}");
    }
}

