import java.util.*;

public class MaxElement {
    public static void main(String[] args) {
        int[] arr1 = {2, 8, 7, 2, 8, 2, 6};

        // Step 1: Create a map to store frequency of each element
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int num : arr1) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        // Step 2: Find the maximum frequency
        int maxFrequency = Collections.max(frequencyMap.values());

        // Step 3: Collect all elements with the maximum frequency
        List<Integer> maxFrequencyElements = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            if (entry.getValue() == maxFrequency) {
                maxFrequencyElements.add(entry.getKey());
            }
        }

        // Step 4: Sort the list in ascending order
        Collections.sort(maxFrequencyElements);

        // Step 5: Print the result
        System.out.println("Max Frequency Elements: " + maxFrequencyElements);
    }
}

