function fetchUser(username, password) {
  queue.push({ username, password });
  processNextRequest();
}

function processNextRequest() {
  if (queue.length === 0) {
    return;
  }

  const now = Date.now();
  const elapsedSeconds = (now - lastMinuteTimestamp) / 1000;

  if (elapsedSeconds >= 60) {
    requestCounter = 0;
    lastMinuteTimestamp = now;
  }

  if (requestCounter >= 5) {
    const delay = Math.max(0, 60000 - elapsedSeconds * 1000); // Delay until the next minute
    setTimeout(processNextRequest, delay);
    return;
  }

  const { username, password } = queue.shift();
  const url = `/users/fetch?username=${username}&password=${password}`;

