// Function to compare two integers for qsort
int compare(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

// Function to remove duplicates and sort the array
void removeDuplicatesAndSort(int arr[], int n, int *uniqueArr, int *uniqueCount) {
    int i;
    int seen[n];
    for (i = 0; i < n; i++) {
        seen[i] = 0;
    }

    *uniqueCount = 0;
    for (i = 0; i < n; i++) {
        if (!seen[arr[i]]) {
            uniqueArr[*uniqueCount] = arr[i];
            (*uniqueCount)++;
            seen[arr[i]] = 1;
        }
    }

    qsort(uniqueArr, *uniqueCount, sizeof(int), compare);
}

int diffSecondMaxSecondMin(int arr[], int n) {
    int uniqueArr[n];
    int uniqueCount;

    removeDuplicatesAndSort(arr, n, uniqueArr, &uniqueCount);

    if (uniqueCount < 2) {
        return -1; // Not enough unique elements
    }

    int second_max = uniqueArr[uniqueCount - 2];
    int second_min = uniqueArr[1];

    return second_max - second_min;
}

int main() {
    int arr[] = {2, 8, 10, 9, 8, 2, 10};
    int n = sizeof(arr) / sizeof(arr[0]);
    int result = diffSecondMaxSecondMin(arr, n);
    if (result == -1) {
        printf("Not enough unique elements.\n");
    } else {
        printf("%d\n", result);
    }
    return 0;
}

