from bs4 import BeautifulSoup
from urllib.parse import urlparse

def get_links(url):
    response = fetch(url)
    if response is None:
        return {'internal': [], 'external': []}

    soup = parse_html(response.text)
    links = []

    for anchor in soup.find_all('a'):
        href = anchor.get('href')
        if href:
            links.append(href)

    for meta in soup.find_all('meta', attrs={'content': True}):
        content = meta.get('content')
        if 'http' in content:
            links.append(content)

    for script in soup.find_all('script', attrs={'src': True}):
        src = script.get('src')
        if src:
            links.append(src)

    domain = extract_domain(url)
    categorized_links = {'internal': [], 'external': []}

    for link in links:
        if is_internal(link, domain):
            categorized_links['internal'].append(link)
        else:
            categorized_links['external'].append(link)

    return categorized_links

def fetch(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response
    except Exception as e:
        print("Error fetching URL:", e)
        return None

def parse_html(html):
    return BeautifulSoup(html, 'html.parser')

def extract_domain(url):
    parsed_url = urlparse(url)
    return parsed_url.netloc

def is_internal(link, domain):
    parsed_link = urlparse(link)
    return parsed_link.netloc == domain or not parsed_link.netloc

if __name__ == '__main__':
    url = "https://www.example.com"
    print(get_links(url))

