def processKeystrokes(input):
    lines = []
    currentLine = ""

    for char in input:
        if char == '<':
            if len(currentLine) > 0:
                currentLine = currentLine[:-1]
        elif char == '\n':
            lines.append(currentLine)
            currentLine = ""
