#include <stdio.h>

void swap_int(int *x, int *y) {
    if (*x == *y) {
        return; // No need to swap if both are the same
    }
    *x = *x ^ *y;
    *y = *x ^ *y;
    *x = *x ^ *y;
}

int main() {
    int a = -1000000000;
    int b = 1000000000;

    printf("Before swap: a = %d, b = %d\n", a, b);
    swap_int(&a, &b);
    printf("After swap: a = %d, b = %d\n", a, b);

    return 0;
}

