public class BubbleSortEnhanced {
    public static int bubbleSort(int[] arr) {
        int n = arr.length;
        int swapCount = 0;
        boolean swapped;
        for (int i = 0; i < n; i++) {
            swapped = false;
            for (int j = 1; j < (n - i); j++) {
                if (arr[j - 1] > arr[j]) {
                    int temp = arr[j - 1];
                    arr[j - 1] = arr[j];
                    arr[j] = temp;
                    swapCount++;
                    swapped = true;
                }
            }
            if (!swapped) {
                break;
            }
        }
        return swapCount;
    }

    public static void main(String[] args) {
        int[] array = {4, 3, 5, 2, 1};
        int swaps = bubbleSort(array);
        System.out.println("Sorted Array: ");
        for (int num : array) {
            System.out.print(num + " ");
        }
        System.out.println("\nNumber of Swaps: " + swaps);
    }
}

