def generatePermutations(lst):
    if len(lst) == 0:
        return []
    if len(lst) == 1:
        return [lst]

    result = []
    for i in range(len(lst)):
        m = lst[i]
        remLst = lst[:i] + lst[i+1:]
        for p in generatePermutations(remLst):
            result.append([m] + p)
    return result

def isValidPermutation(original, perm):
    for i in range(len(original) - 1):
        if original[i] == original[i+1] and perm[i] == perm[i+1]:
            return False
    return True

def filterPermutations(original, permutations):
    validPermutations = []
    for perm in permutations:
        if isValidPermutation(original, perm):
            validPermutations.append(perm)
    return validPermutations

def enhancedPermutation(lst):
    allPermutations = generatePermutations(lst)
    return filterPermutations(lst, allPermutations)

