function extractTableElements(htmlContent):
    tableElements = []
    startIndex = 0
    while true:
        tableStart = htmlContent.find("<table", startIndex)
        if tableStart == -1:
            break
        tableEnd = findClosingTagIndex(htmlContent, tableStart)
        if tableEnd == -1:
            break
        tableElement = htmlContent.substring(tableStart, tableEnd + 8) // 8 is the length of "</table>"
        tableElements.append(tableElement)
        startIndex = tableEnd + 8
    return tableElements

function findClosingTagIndex(htmlContent, tableStart):
    stack = []
    index = tableStart
    while index < htmlContent.length:
        openTagStart = htmlContent.find("<table", index)
        closeTagStart = htmlContent.find("</table>", index)
        if openTagStart != -1 and (closeTagStart == -1 or openTagStart < closeTagStart):
            stack.push(openTagStart)
            index = openTagStart + 6 // 6 is the length of "<table"
        elif closeTagStart != -1:
            if stack.isEmpty():
                return closeTagStart
            else:
                stack.pop()
                index = closeTagStart + 8 // 8 is the length of "</table>"
        else:
            break
    return -1
```

