function handleClientRequest(client):
    try:
        request = readRequestFromClient(client)
        if request.type == "READ":
            result = executeReadQuery(request.query)
            sendResultToClient(client, result)
        else if request.type == "WRITE":
            executeWriteTransaction(request.transaction)
            sendConfirmationToClient(client)
    catch Exception as e:
        sendErrorToClient(client, e.message)
    finally:
        closeClientConnection(client)

function executeReadQuery(query):
    return database.executeQuery(query)

function executeWriteTransaction(transaction):
    database.beginTransaction()
    try:
        for operation in transaction.operations:
            database.executeOperation(operation)
        database.commitTransaction()
    except Exception as e:
        database.rollbackTransaction()
        throw e

function sendResultToClient(client, result):
    client.send(result)

function sendConfirmationToClient(client):
    client.send("Transaction successful")

function sendErrorToClient(client, errorMessage):
    client.send(errorMessage)
