class Person 
  attr_accessor :name, :age, :gender, :address 

  def initialize(name, age, gender, address, birthdate) 
    @name = name 
    @age = age
    @gender = gender
    @address = address
    @birthdate = Date.parse(birthdate)
  end 

  def update_address(new_address)
    @address = new_address
  end

  def calculate_age(current_date)
    current = Date.parse(current_date)
    age_years = current.year - @birthdate.year
    age_months = current.month - @birthdate.month
    age_days = current.day - @birthdate.day

    if age_days < 0
      age_months -= 1
      age_days += (current.prev_month >> 1).day
    end

    if age_months < 0
      age_years -= 1
      age_months += 12
    end

    { years: age_years, months: age_months, days: age_days }
  end
end

