public class QuickSortWithSwapCount {

    public static int quickSort(int[] arr, int low, int high) {
        if (arr == null || arr.length == 0)
            return 0;

        if (low >= high)
            return 0;

        int swapCount = 0;
        int middle = low + (high - low) / 2;
        int pivot = arr[middle];

        int i = low, j = high;
        while (i <= j) {
            while (arr[i] < pivot) {
                i++;
            }

            while (arr[j] > pivot) {
                j--;
            }

            if (i <= j) {
                if (arr[i] != arr[j]) {
                    swap(arr, i, j);
                    swapCount++;
                }
                i++;
                j--;
            }
        }

        swapCount += quickSort(arr, low, j);
        swapCount += quickSort(arr, i, high);

        return swapCount;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        int[] arr = {3, 6, 8, 10, 1, 2, 1};
        int swapCount = quickSort(arr, 0, arr.length - 1);
        System.out.println("Sorted Array: ");
        for (int num : arr) {
            System.out.print(num + " ");
        }
        System.out.println("\nNumber of Swaps: " + swapCount);
    }
}

