import sys
import os
import tarfile

def main():
    if len(sys.argv) < 2:
        print("Usage: python script.py dir1 [dir2 ... dirN]")
        return

    for directory in sys.argv[1:]:
        if not os.path.exists(directory):
            print(f"Directory {directory} does not exist.")
            continue
        if not os.access(directory, os.R_OK):
            print(f"Permission denied for directory {directory}.")
            continue
        try:
            create_tar_archive(directory)
            print(f"Successfully created archive for {directory}.")
        except Exception as e:
            print(f"Failed to create archive for {directory}: {e}")

def create_tar_archive(directory):
    archive_name = directory + ".tar"
    with tarfile.open(archive_name, "w") as tar:
        tar.add(directory, arcname=os.path.basename(directory))

if __name__ == "__main__":
    main()

