function longestIncreasingSubsequence(arr):
    n = length(arr)
    dp = array of size n filled with 1
    prev = array of size n filled with -1
    maxLength = 0
    endIndex = -1

    for i from 0 to n-1:
        for j from 0 to i-1:
            if arr[i] > arr[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev[i] = j
        if dp[i] > maxLength:
            maxLength = dp[i]
            endIndex = i

    lis = []
    while endIndex != -1:
        lis.append(arr[endIndex])
        endIndex = prev[endIndex]
    lis.reverse()

    // Check for lexicographically smallest sequence
    for i from 0 to n-1:
        if dp[i] == maxLength:
            candidate = []
            index = i
            while index != -1:
                candidate.append(arr[index])
                index = prev[index]
            candidate.reverse()
            if candidate < lis:
                lis = candidate

    return lis
```

