# prime number sieve
def prime_numbers(n): 

    prime = [True for i in range(n+1)] 
    p = 2
    while (p * p <= n): 
        if (prime[p] == True): 
            for i in range(p * p, n+1, p): 
                prime[i] = False
        p += 1

    prime_numbers_list = []
    for p in range(2, n): 
        if prime[p]: 
            prime_numbers_list.append(p)

    first_ten_primes = prime_numbers_list[:10]
    sum_of_primes = sum(first_ten_primes)
    product_of_primes = 1
    for num in first_ten_primes:
        product_of_primes *= num

    return first_ten_primes, sum_of_primes, product_of_primes

if __name__ == "__main__":
