def find_first_common_element(list1, list2):
    def is_nested(element):
        return isinstance(element, (list, tuple))

    def find_common_recursive(sublist1, sublist2):
        for element1 in sublist1:
            if is_nested(element1):
                for element2 in sublist2:
                    if is_nested(element2):
                        result = find_common_recursive(element1, element2)
                        if result is not None:
                            return result
                    elif element1 == element2:
                        return element1
            else:
                for element2 in sublist2:
                    if element1 == element2:
                        return element1
        return None

    return find_common_recursive(list1, list2)

