public class Factorial {

  public static long calcFactorialIterative(int number) {
    long factorial = 1;
    for (int i = 2; i <= number; i++) {
      factorial *= i;
    }
    return factorial;
  }

  public static long calcFactorialRecursive(int number) {
    if (number == 0 || number == 1) {
      return 1;
    } else {
      return number * calcFactorialRecursive(number - 1);
    }
  }

  public static void main(String[] args) {
    int number = 5;

    // Measure iterative method execution time
    long startTimeIterative = System.nanoTime();
    long resultIterative = calcFactorialIterative(number);
    long endTimeIterative = System.nanoTime();

    // Measure recursive method execution time
    long startTimeRecursive = System.nanoTime();
    long resultRecursive = calcFactorialRecursive(number);
    long endTimeRecursive = System.nanoTime();

    // Print results and execution times
    System.out.println("Iterative Factorial of " + number + ": " + resultIterative);
    System.out.println("Execution Time (Iterative): " + (endTimeIterative - startTimeIterative) + " nanoseconds");

    System.out.println("Recursive Factorial of " + number + ": " + resultRecursive);
    System.out.println("Execution Time (Recursive): " + (endTimeRecursive - startTimeRecursive) + " nanoseconds");
  }
}

