using namespace std;

// Function to calculate character frequency
vector<int> calculateFrequency(const string& s) {
    vector<int> freq(26, 0);
    for (char c : s) {
        freq[c - 'a']++;
    }
    return freq;
}

// Custom comparator function
bool customComparator(const string& a, const string& b) {
    vector<int> freqA = calculateFrequency(a);
    vector<int> freqB = calculateFrequency(b);

    for (int i = 0; i < 26; ++i) {
        if (freqA[i] != freqB[i]) {
            return freqA[i] > freqB[i];
        }
    }

    return a < b;
}

// Function to sort strings based on custom criteria
void sortStringsByFrequency(vector<string>& strings) {
    sort(strings.begin(), strings.end(), customComparator);
}

int main() {
    vector<string> strings = {"apple", "banana", "cherry", "date"};
    sortStringsByFrequency(strings);

