import sys

def calculate_total_memory_usage(data_structure):
    visited = set()
    return recursive_sizeof(data_structure, visited)

def recursive_sizeof(obj, visited):
    obj_id = id(obj)
    if obj_id in visited:
        return 0
    visited.add(obj_id)
    size = sys.getsizeof(obj)
    if isinstance(obj, (list, tuple, set)):
        for item in obj:
            size += recursive_sizeof(item, visited)
    elif isinstance(obj, dict):
        for key, value in obj.items():
            size += recursive_sizeof(key, visited)
            size += recursive_sizeof(value, visited)
    return size

