#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

vector<int> addVectors(const vector<int>& a, const vector<int>& b) {
    vector<int> result;
    int carry = 0;
    auto itA = a.rbegin();
    auto itB = b.rbegin();

    while (itA != a.rend() || itB != b.rend() || carry != 0) {
        int sum = carry;
        if (itA != a.rend()) {
            sum += *itA;
            ++itA;
        }
        if (itB != b.rend()) {
            sum += *itB;
            ++itB;
        }
        result.push_back(sum % 2);
        carry = sum / 2;
    }

    reverse(result.begin(), result.end());
    return result;
}

string vectorToBinaryString(const vector<int>& v) {
    string result;
    for (int bit : v) {
        result += to_string(bit);
    }
    return result;
}

