    vector<int> f1 = {0};
    vector<int> f2 = {1};

    cout << vectorToBinaryString(f2) << " ";

    for (int i = 1; i < n; ++i) {
        vector<int> next = addVectors(f1, f2);
        cout << vectorToBinaryString(next) << " ";
        f1 = f2;
        f2 = next;
    }
}

