import csv
import json

def csv_to_json(file_csv='mycsvfile.csv', file_json='myjsonfile.json'):
    with open(file_csv, 'r', newline='') as input_file, open(file_json, 'w') as output_file:
        reader = csv.DictReader(input_file)
        data = []

        for row in reader:
            processed_row = {}
            for key, value in row.items():
                try:
                    num_value = float(value)
                    if num_value.is_integer():
                        processed_row[key] = int(num_value)
                    else:
                        processed_row[key] = num_value
                except ValueError:
                    processed_row[key] = value
            data.append(processed_row)

        json.dump(data, output_file)

