function customFadeIn(elements) {
    elements.forEach(function(item) {
        var startTime = null;
        var element = $(item.selector);
        var duration = item.duration || 1000; // default duration 1 second
        var easingFunction = item.easing || easeInOutQuad; // default easing function

        function step(timestamp) {
            if (!startTime) startTime = timestamp;
            var progress = timestamp - startTime;
            var opacity = easingFunction(progress / duration);

            if (progress < duration) {
                element.css('opacity', opacity);
                requestAnimationFrame(step);
            } else {
                element.css('opacity', 1); // ensure it reaches full opacity
            }
        }

        element.css('opacity', 0); // start with opacity 0
        requestAnimationFrame(step);
    });
}

function easeInOutQuad(t) {
    return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
}

