def gcd(a, b):
    while b != 0:
        temp = b
        b = a % b
        a = temp
    return a

def average(a, b):
    total_sum = a + b
    if total_sum % 2 == 0:
        return total_sum // 2
    else:
        numerator = total_sum
        denominator = 2
        divisor = gcd(numerator, denominator)
        return (numerator // divisor, denominator // divisor)

# Example usage:
print(average(3, 7))  # Output: (5, 1)
print(average(1, 2))  # Output: (3, 2)

