import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class SyntaxChecker {

    public static List<String> checkJavaSyntax(String code) {
        List<String> errors = new ArrayList<>();
        File tempFile = null;
        try {
            // Create a temporary Java file
            tempFile = File.createTempFile("temp", ".java");
            FileWriter writer = new FileWriter(tempFile);
            writer.write(code);
            writer.close();

            // Compile the Java file
            Process process = Runtime.getRuntime().exec("javac " + tempFile.getAbsolutePath());
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                errors.add(line);
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        } finally {
            // Clean up the temporary file
            if (tempFile != null) {
                tempFile.delete();
            }
        }
        return errors;
    }

    public static void main(String[] args) {
        String code = "public class Test {\n" +
                      "    public static void main(String[] args) {\n" +
                      "        System.out.println(\"Hello, World!\"\n" +
                      "    }\n" +
                      "}\n";
        List<String> errors = checkJavaSyntax(code);
        if (errors.isEmpty()) {
            System.out.println("No syntax errors found.");
        } else {
            System.out.println("Syntax errors found:");
            for (String error : errors) {
                System.out.println(error);
            }
        }
    }
}

