public class StringSplitter {
    public static void main(String[] args) {
        String input = "HelloWorld";
        char targetChar = 'o';

        String[] result = splitStringByLastOccurrence(input, targetChar);
        System.out.println("First Piece: " + result[0]);
        System.out.println("Second Piece: " + result[1]);
    }

    public static String[] splitStringByLastOccurrence(String inputString, char targetChar) {
        int lastPosition = inputString.lastIndexOf(targetChar);
        if (lastPosition == -1) {
            return new String[]{inputString, ""};
        } else {
            return new String[]{inputString.substring(0, lastPosition + 1), inputString.substring(lastPosition + 1)};
        }
    }
}

