def sort_string_with_spaces(string):
    space_positions = []
    non_space_chars = []

    # Collect space positions and non-space characters
    for i, char in enumerate(string):
        if char == ' ':
            space_positions.append(i)
        else:
            non_space_chars.append(char)

    # Sort non-space characters
    non_space_chars.sort()

    # Reconstruct the string with sorted characters and original spaces
    result = []
    char_index = 0
    for i in range(len(string)):
        if i in space_positions:
            result.append(' ')
        else:
            result.append(non_space_chars[char_index])
            char_index += 1

    return ''.join(result)

# Example usage:
string = "hello world"
sorted_string = sort_string_with_spaces(string)
print(sorted_string)  # Output: "dehllloorw "

