def reorder_string(s):
    letters = []
    digits = []

    for char in s:
        if char.isalpha():
            letters.append(char)
        elif char.isdigit():
            digits.append(char)

    letters.sort()
    digits.sort()

    return ''.join(letters) + ''.join(digits)

